function esc(v) {
  return String(v ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function get(path) {
  return path.split(".").reduce((a, k) => a?.[k], config);
}

function set(path, value) {
  const p = path.split(".");
  let o = config;
  for (let i = 0; i < p.length - 1; i++) {
    if (!o[p[i]] || typeof o[p[i]] !== "object") o[p[i]] = {};
    o = o[p[i]];
  }
