async function restoreLastIndex() {
  const loaded = await autoLoadIndex();
  if (loaded) return;
  const h = await getPersistedFileHandle();
  if (h) {
    await loadFromHandle(h, true);
  } else {
    setStatus("Pronto — Use 📂 Abrir ou 💾 Salvar index.html", false);
  }
}

function showFrame() {
  const wrap = $("frameWrap");
  const frame = $("gameFrame");
  if (!wrap || !frame) return;
  wrap.classList.add("show");
  if (indexText) {
    const blob = new Blob([indexText], { type: "text/html" });
    frame.src = URL.createObjectURL(blob);
  } else {
    frame.src = "index.html";
  }
}

