window.GenesisGame = {

    get(path, fallback = null){

        const parts =
            String(path)
                .split(".")
                .filter(Boolean);

        let value =
            window.GENESIS_GAME.data;

        for(const part of parts){

            if(
                value === null ||
                value === undefined
            )
                return fallback;

            value = value[part];

        }

        return value === undefined
            ? fallback
            : value;

    },

set(path,value){

        const parts =
            String(path)
                .split(".")
                .filter(Boolean);

        let target =
            window.GENESIS_GAME.data;

        for(let i=0;i<parts.length-1;i++){

            const part=parts[i];

            if(
                !target[part] ||
                typeof target[part] !== "object"
            ){

                target[part]={};

            }

            target=target[part];

        }

        target[
            parts[parts.length-1]
        ]=value;

        window.applyGenesisEditorData(
            window.GENESIS_GAME.data
        );

    }

};
